// ledger.wasm — drives the Rust/WASM engine (doppio parse + report layer).
// No bundler: pkg/ is generated by build-wasm.sh (wasm-bindgen, target web).

import init, { Engine } from "./pkg/ledger_reports_wasm.js";

const $ = (id) => document.getElementById(id);

const SAMPLE = `; demo journal — balances verified against ledger-cli
2024-01-01 * Opening balances
    Assets:Checking           $2500.00
    Equity:Opening Balances

2024-01-02 * Paycheck (salary)
    Assets:Checking           $3000.00
    Income:Salary

2024-01-05 Grocery run
    Expenses:Food             $82.40
    Assets:Checking

2024-01-08 * Phone bill
    Expenses:Utilities        $45.00
    Expenses:Internet         $20.00
    Assets:Checking           -$65.00

2024-01-10 * Buy 10 AAPL (cost basis tracked)
    Assets:Brokerage          10 AAPL {$185.00} @ $185.00
    Assets:Checking

2024-01-12 * London trip (currency conversion via @)
    Expenses:Travel           420.00 EUR @ $1.09
    Assets:Checking

2024-01-15 * Sell 5 AAPL (gain over cost booked explicitly)
    Assets:Brokerage          -5 AAPL {$185.00} @ $196.00
    Assets:Checking           $980.00
    Income:Capital Gains      $-55.00

2024-01-20 Balance assertion on running total
    Assets:Checking           $0.00 = $4024.80
    Expenses:Gifts

2024-01-31 * Month-end interest
    Assets:Checking           $12.15
    Income:Interest

account Assets:Checking
    note main account, cleared monthly

commodity $
    format $1,000.00
`;

function setStatus(msg, ok = false) {
  const el = $("status");
  el.textContent = msg;
  el.classList.toggle("ok", ok);
}

function showError(msg) {
  const el = $("error");
  // doppio errors embed " --> LINE:COL"; make the first line pop
  const lines = String(msg).split("\n");
  el.textContent = lines.join("\n");
  el.hidden = false;
  setStatus("compile failed");
}

function clearError() {
  $("error").hidden = true;
}

function esc(s) {
  const d = document.createElement("div");
  d.textContent = s;
  return d.innerHTML;
}

// --- report renderers -------------------------------------------------------

function renderBalance(rep) {
  const rows = rep.rows
    .map((r) => {
      const amts = r.amounts
        .map((a) => `<span class="amt ${a.trim().startsWith("-") ? "neg" : "pos"}">${esc(a)}</span>`)
        .join("");
      const indent = "&nbsp;".repeat((r.depth - 1) * 2);
      const isParent = r.depth < maxDepthOf(rep.rows);
      return `<div class="bal-row ${r.depth === maxDepthOf(rep.rows) ? "leaf" : "parent"}">
        <span class="acct">${indent}${esc(r.account)}</span>
        <span class="amts">${amts}</span>
      </div>`;
    })
    .join("");
  const total = rep.total
    .map((a) => `<span class="amt ${a.trim().startsWith("-") ? "neg" : "pos"}">${esc(a)}</span>`)
    .join("");
  $("report").innerHTML =
    rows +
    (total ? `<div class="bal-total"><span class="label">total</span><span class="amts">${total}</span></div>` : "");
  $("report-title").textContent = "balance (tree)";
}

function maxDepthOf(rows) {
  return Math.max(...rows.map((r) => r.depth));
}

function renderRegister(rep) {
  if (!rep.transactions.length) {
    $("report").innerHTML = '<div class="placeholder">no transactions</div>';
    return;
  }
  $("report").innerHTML = rep.transactions
    .map((t, i) => {
      const posts = t.postings
        .map(
          (p) =>
            `<div class="post"><span class="acct">${esc(p.account)}</span><span class="amt">${
              p.commodity === "$"
                ? esc(p.amount.startsWith("-") ? "-$" + p.amount.slice(1) : "$" + p.amount)
                : esc(p.amount + " " + p.commodity)
            }</span></div>`
        )
        .join("");
      return `<div class="txn" data-i="${i}">
        <div class="txn-head"><span class="date">${esc(t.date)}</span>
          <span class="state">${t.state === "cleared" ? "*" : t.state === "pending" ? "!" : ""}</span>
          <span class="desc">${esc(t.description)}</span></div>
        ${posts}
      </div>`;
    })
    .join("");
  $("report-title").textContent = `register (${rep.transactions.length} transactions)`;
}

function renderAccounts(accounts) {
  $("report").innerHTML =
    `<div class="chips">` +
    accounts.map((a) => `<span class="chip">${esc(a)}</span>`).join("") +
    `</div>`;
  $("report-title").textContent = `accounts (${accounts.length})`;
}

// --- engine invocation -----------------------------------------------------

let engine = null;
let engineKey = null; // source+frontend cache key

function getEngine() {
  const source = $("source").value;
  const format = $("frontend").value;
  const key = format + "\u0000" + source;
  if (engine && engineKey === key) return engine;
  clearError();
  engine = new Engine(source, format); // throws on parse/elaboration error
  engineKey = key;
  return engine;
}

async function run(kind) {
  const buttons = ["btn-balance", "btn-register", "btn-accounts"];
  buttons.forEach((b) => ($(b).disabled = true));
  const t0 = performance.now();
  try {
    const e = getEngine();
    const ms = (performance.now() - t0).toFixed(1);
    if (kind === "bal") {
      renderBalance(e.balance());
      setStatus(`balanced OK — compiled+reported in ${ms}ms`, true);
    } else if (kind === "reg") {
      renderRegister(e.register());
      setStatus(`ok — ${ms}ms`, true);
    } else {
      renderAccounts(e.accounts());
      setStatus(`ok — ${ms}ms`, true);
    }
  } catch (err) {
    engine = null;
    engineKey = null;
    showError(err?.message ?? err);
    $("report").innerHTML = '<div class="placeholder">fix the error, then run a report</div>';
    $("report-title").textContent = "report";
  } finally {
    buttons.forEach((b) => ($(b).disabled = false));
  }
}

$("btn-balance").addEventListener("click", () => run("bal"));
$("btn-register").addEventListener("click", () => run("reg"));
$("btn-accounts").addEventListener("click", () => run("accounts"));
$("btn-sample").addEventListener("click", () => {
  $("source").value = SAMPLE;
  engine = null;
  clearError();
  run("bal");
});
$("frontend").addEventListener("change", () => {
  engine = null;
  clearError();
});
// Cmd/Ctrl+Enter runs balance
$("source").addEventListener("keydown", (ev) => {
  if ((ev.metaKey || ev.ctrlKey) && ev.key === "Enter") run("bal");
});

// boot. Hash params allow deep-linking views in headless tests:
//   #view=reg | #view=accounts | #broken=1
await init();
const boot = new URLSearchParams(location.hash.replace(/^#/, ""));
if (boot.get("broken") === "1") {
  $("source").value =
    "2024-02-01 * Broken transaction\n    Expenses:Stuff            $10.00\n    Assets:Checking           $3.00\n";
} else {
  $("source").value = SAMPLE;
}
await run(boot.get("view") ?? "bal");
if (boot.get("broken") !== "1") setStatus("wasm engine ready — sample journal loaded", true);